int s_neg = -10;
unsigned int u_pos = 5;

// Trap 1: Comparison Promotion
// s_neg is converted to unsigned (UINT_MAX - 9)
bool trap_comp = (s_neg > u_pos); // Evaluates to true

// Trap 2: Arithmetic Wrap-around
// Result is calculated as unsigned int
// -10 + 5 = -5
unsigned int large_pos_result = s_neg + u_pos;
// large_pos_result holds UINT_MAX - 4

// Standard Promotion (Narrow types to int)
short s_val = 1;
char c_val = 2;
auto type_promoted = decltype(s_val + c_val); // 'int'

// Correcting the trap: Cast to signed explicitly
bool correct_comp = (s_neg > static_cast<int>(u_pos)); // false
